export interface ValidatePlanInput {
  workingDir: string;
  planFile: string;
  transcriptPath?: string;
  sessionDir?: string;
  continueWorkflow?: boolean;
}

export interface PlanValidationRunResult {
  status: "PASS" | "FAIL";
  reasons: string[];
  resolvedPath?: string;
  content?: string;
  contentHash?: string;
}

function getHookName(): string { return activeSpec().mcpWireName("validate_plan"); }

export function formatPlanValidationPassInstructions(continueWorkflow = false): string {
  if (continueWorkflow) {
    return "Validation passed. Continue with the next step of the invoking plan workflow instead of presenting the plan now.";
  }
  return "Now present the complete contents of the validated planfile inside a whole-message <proposed_plan>...</proposed_plan> block. Do not summarize it or replace it with only the plan name, planfile path, or validation status.";
}

function formatResult(
  status: "PASS" | "FAIL",
  reasons: readonly string[],
  planPath?: string,
  validatePlanWireName?: string,
  continueWorkflow = false,
): string {
  if (status === "PASS" && reasons.length === 0) {
    return `## Results
- Status: ${status}

## Instructions
${formatPlanValidationPassInstructions(continueWorkflow)}`;
  }
  const body = reasons.length > 0 ? reasons.join("\n") : "(none)";
  const instructions = planPath && validatePlanWireName
    ? `\n\n## Instructions\n${formatPlanfileValidationWorkflow(planPath, validatePlanWireName)}`
    : "";
  return `## Results
- Status: ${status}

## Reasons
${body}${instructions}`;
}

function stripViolationPrefix(text: string): string {
  return text.replace(/^\[VIOLATION: ([^\]]+)\]\s*/, "$1: ");
}

function uniqueReasons(reasons: readonly string[]): string[] {
  return [...new Set(reasons)];
}

function hasSpecificInvalidReason(text: string): boolean {
  const reason = text.replace(/^INVALID:\s*/i, "").trim();
  if (!reason) return false;
  if (/^(the plan|plan)\s+(does not|doesn't|fails to)\s+(follow|satisfy|meet)/i.test(reason)) return false;
  if (/\b(missing|required|extra|duplicate|helper|reuse|shared|repeated|similar|location|heading|section|line|rule|contract|verification|specific|vague|unresolved|schedule|option|blacklisted)\b/i.test(reason)) return true;
  return /##\s+\S+|\b(User Goal|Answered Assumptions|Goal In My Words|Approach|Data Flow|Files To Create|Files To Modify|Implementation Order|Assistant Verification|Manual User Verification|Approaches Decided Against|Possible Future Followups|Relevant Files|Files That Need Changes)\b/i.test(reason);
}

function resolvePlanContent(input: ValidatePlanInput): { content?: string; resolvedPath?: string; error?: string } {
  if (typeof input.planFile !== "string" || !input.planFile.trim()) {
    return { error: "plan_file is required." };
  }
  const file = input.planFile;
  const resolved = path.isAbsolute(file) ? file : path.resolve(input.workingDir, file);
  try {
    return { content: fs.readFileSync(resolved, "utf-8"), resolvedPath: resolved };
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return { error: `Could not read plan_file ${resolved}: ${msg}`, resolvedPath: resolved };
  }
}

export async function runValidatePlanAgent(
  input: ValidatePlanInput,
  options: CancellationOptions = {},
): Promise<string> {
  const result = await validatePlanFileWithContract(input, options);
  const validatePlanWireName = mcpWireNameForText(
    "validate_plan",
    result.content ?? result.reasons.join("\n"),
  );
  return formatResult(
    result.status,
    result.reasons,
    result.resolvedPath,
    validatePlanWireName,
    input.continueWorkflow,
  );
}

function recordValidationResult(input: ValidatePlanInput, result: PlanValidationRunResult): void {
  if (!result.resolvedPath || result.contentHash === undefined) return;
  let sessionDir = input.sessionDir ??
    (input.transcriptPath
      ? getAgentFrameworkSessionDir({ transcriptPath: input.transcriptPath })
      : undefined);
  if (!sessionDir) {
    try {
      sessionDir = getAgentFrameworkSessionDir({ projectDir: input.workingDir });
    } catch {
      sessionDir = undefined;
    }
  }
  if (!sessionDir) return;
  recordPlanValidationStatus({
    sessionDir,
    planPath: result.resolvedPath,
    contentHash: result.contentHash,
    status: result.status === "PASS" ? "pass" : "fail",
    reasons: result.reasons,
  });
}

